import java.util.*;

public class Main {
    static int sumEven(List<Integer> nums) {
        int total = 0;
        for (int n : nums) {          // for-each: как for in в Python
            if (n % 2 == 0) total += n;
        }
        return total;
    }

    public static void main(String[] args) {
        List<Integer> data = Arrays.asList(1, 2, 3, 4, 5, 6);
        System.out.println(sumEven(data));   // 12
    }
}

