        for (String w : words) {
            counts.put(w, counts.getOrDefault(w, 0) + 1);   // как dict.get(w, 0) + 1
        }
        return counts;
    }

    public static void main(String[] args) {
        System.out.println(countWords(new String[]{"java", "sql", "java"}));
