import java.util.*;

interface Shape {
    double area();                  // только объявление, без тела
    String name();
}

class Circle implements Shape {
    private final double r;
    Circle(double r) { this.r = r; }
    public double area() { return Math.PI * r * r; }
    public String name() { return "круг"; }
}

class Square implements Shape {
    private final double side;
    Square(double side) { this.side = side; }
    public double area() { return side * side; }
    public String name() { return "квадрат"; }
}

public class Main {
    public static void main(String[] args) {
        List<Shape> shapes = Arrays.asList(new Circle(1), new Square(3));
        for (Shape s : shapes) {
            System.out.printf("%s: %.2f%n", s.name(), s.area());
        }
    }
}

public class Main {
    static int divide(int a, int b) {
        if (b == 0) {
            throw new IllegalArgumentException("делить на ноль нельзя");
        }
        return a / b;
    }

    public static void main(String[] args) {
        System.out.println(divide(10, 2));

        try {
            System.out.println(divide(5, 0));
        } catch (IllegalArgumentException e) {
            System.out.println("поймали: " + e.getMessage());
        } finally {
            System.out.println("finally выполняется всегда");
        }

        System.out.println("программа продолжает работу");
    }
}

