import java.util.*;

public class Main {
    static String topWord(String[] words) {
        Map<String, Integer> counts = new HashMap<>();
        for (String w : words) {
            counts.put(w, counts.getOrDefault(w, 0) + 1);
        }

        String best = "";
        int max = -1;
        for (Map.Entry<String, Integer> e : counts.entrySet()) {
            if (e.getValue() > max) {
                max = e.getValue();
                best = e.getKey();
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(topWord(new String[]{"java", "sql", "java", "c", "java"}));
    }
}
